function wrongs(pool,right,n,near){const out=[];const cand=pool.filter(x=>x!==right);(near||[]).forEach(x=>{if(cand.includes(x)&&!out.includes(x)&&out.length<n)out.push(x)});
 const rest=cand.filter(x=>!out.includes(x));for(let i=rest.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[rest[i],rest[j]]=[rest[j],rest[i]];}
 return out.concat(rest).slice(0,n);}
