(function(){
const E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
window.qbox=function(t){
  const m=/^§([FPDE]):([^§]*)§([\s\S]*)$/.exec(t||'');
  if(!m)return '<div class="q">'+E(t)+'</div>';
  const k=m[1],v=m[2],txt=E(m[3]);let media='';
  if(k==='F'){const svg=(window.FLAGS||{})[v]||'';media='<div class="qmedia flag"><img alt="" src="data:image/svg+xml,'+encodeURIComponent(svg)+'"></div>';}
  else if(k==='P')media='<div class="qmedia photo"><img alt="" src="'+E(v)+'" onerror="this.parentNode.classList.add(\'fail\')"><span class="phf">📷 الصورة محتاجة نت</span></div>';
  else if(k==='D')media='<div class="qmedia date"><small>📅 التاريخ</small><b>'+E(v)+'</b></div>';
  else media='<div class="qmedia emo">'+E(v)+'</div>';
  return media+'<div class="q sm">'+txt+'</div>';
};
const colors=['#ffd23f','#ff5c8a','#2ee6a6','#4d9dff','#a78bfa','#ff9f43'];
window.burst=function(n){
  if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;
  n=n||14;const box=document.createElement('div');box.className='confetti';
  for(let i=0;i<n;i++){const p=document.createElement('i');const a=Math.random()*Math.PI*2,d=90+Math.random()*170;
    p.style.cssText='--x:'+Math.cos(a)*d+'px;--y:'+(Math.sin(a)*d-70)+'px;--r:'+(Math.random()*720-360)+'deg;background:'+colors[i%colors.length]+';animation-delay:'+(Math.random()*.08)+'s';
    box.appendChild(p);}
  document.body.appendChild(box);setTimeout(()=>box.remove(),1300);
};
window.shake=function(){const a=document.querySelector('.lg-app');if(!a)return;a.classList.remove('shake');void a.offsetWidth;a.classList.add('shake');};
})();
